local ActivityGachaponTowerEntryRewardNode = Class("ActivityGachaponTowerEntryRewardNode")
local GoodsNodeMBPath = "Game.Behaviours.GoodNodeMB" -- 物品 Node 的 脚本路径
local ActivityGachaponTowerMgr = import('Game.Activity.GachaponTower.ActivityGachaponTowerMgr')

local RewardType = {
    Down = 1,
    UpOne = 2,
    UpTwo = 3,
    UpNext = 4,
}

function ActivityGachaponTowerEntryRewardNode:__init()

end

function ActivityGachaponTowerEntryRewardNode:__delete()
    self.controller = nil
end

function ActivityGachaponTowerEntryRewardNode:Awake()
    self:SetSpecialEffectActive(false)
    SetButtonAction(self.BtnAdd,Bind(self,self.OnBtnAddClick))
end

function ActivityGachaponTowerEntryRewardNode:RefreshShow(data, chooseData, isShow)
    self.data = data
    self.chooseData = chooseData
    local isChoose = self.data.isChoose == 1
    if isChoose then
        local chooseIndex = chooseData[tostring(self.data.id)]
        if isNotNull(chooseIndex) then
            CfUtils.SetActive(self.BtnAdd.gameObject,false)
            CfUtils.SetActive(self.Layout.gameObject,true)
            CfUtils.SetActive(self.ImgExchange.gameObject,true)
            local reward = self.data.chooseRewards[chooseIndex]
            if isNotNull(reward) then
                self:RefreshGoodNodeShow(reward)
            end
        else
            CfUtils.SetActive(self.BtnAdd.gameObject,true)
            CfUtils.SetActive(self.ImgExchange.gameObject,false)
            if not isNull(self.GoodNode) then
                CfUtils.SetActive(self.GoodNode.gameObject,false)
            end
        end
    else
        self:RefreshGoodNodeShow(self.data.rewards[1])
    end

    local isEnd = ActivityGachaponTowerMgr:GetInstance():IsDrawOver()
    local isFinish = (self.data.stock == 0) or isEnd
    CfUtils.SetActive(self.FInish.gameObject,isFinish)

    local rewardType = self.data.rewardType
    if rewardType == RewardType.Down then
        CfUtils.SetActive(self.ImgSymbolL.gameObject,false)
        CfUtils.SetActive(self.ImgSymbolR.gameObject,false)
    elseif rewardType == RewardType.UpOne then
        CfUtils.SetActive(self.ImgSymbolL.gameObject,false)
        CfUtils.SetActive(self.Layout.gameObject,true)
        CfUtils.SetActive(self.ImgSymbolR.gameObject,true)
        CfUtils.SetUISwitchImage(self.ImgSymbolR,1)
    elseif rewardType == RewardType.UpTwo then
        CfUtils.SetActive(self.ImgSymbolL.gameObject,true)
        CfUtils.SetActive(self.ImgSymbolR.gameObject,false)
        CfUtils.SetUISwitchImage(self.ImgSymbolL,2)
    elseif rewardType == RewardType.UpNext then
        CfUtils.SetActive(self.ImgSymbolL.gameObject,true)
        CfUtils.SetActive(self.ImgSymbolR.gameObject,false)
        CfUtils.SetUISwitchImage(self.ImgSymbolL,3)
    end
    self:SetSpecialEffectActive(isShow)
end

function ActivityGachaponTowerEntryRewardNode:SetSpecialEffectActive(state)
    CfUtils.SetActive(self.UIFX_SpecialGlow.gameObject,state)
end

function ActivityGachaponTowerEntryRewardNode:SetEffectActive(state)
    CfUtils.SetActive(self.ImgGachaponFinalSelect.gameObject,state)
end

function ActivityGachaponTowerEntryRewardNode:SetFinishEffectActive()
    CfUtils.SetActive(self.UIFX_GetGlow.gameObject,true)
end

function ActivityGachaponTowerEntryRewardNode:InitNodeEffect()
    self:SetEffectActive(false)
    CfUtils.SetActive(self.UIFX_GetGlow.gameObject,false)
end

function ActivityGachaponTowerEntryRewardNode:RefreshAddShow(data)
    CfUtils.SetActive(self.BtnAdd.gameObject,false)
    CfUtils.SetActive(self.Layout.gameObject,true)
    CfUtils.SetActive(self.ImgExchange.gameObject,true)

    local reward = self.data.chooseRewards[data.index]
    if isNotNull(reward) then
        self:RefreshGoodNodeShow(reward)
    end
end

function ActivityGachaponTowerEntryRewardNode:RefreshGoodNodeShow(data)
    if isNull(self.GoodNode) then
        self.GoodNode = self.GoodNodeStub:InstantiatePrefab("GoodNode")
        local rect = self.GoodNode.gameObject:GetComponent("RectTransform")
        rect.pivot = Vector2.New(0.5, 0.5)
        rect.anchoredPosition = Vector3.New(0, 0, 0)
        rect.anchorMax = Vector2.New(0.5, 0.5)
        rect.anchorMin = Vector2.New(0.5, 0.5)
    end
    CfUtils.SetActive(self.GoodNode.gameObject, true)
    ---存在该节点将 父节点的缩放丢到该节点上
    ---@type Game.Native.Common.ReverseScale
    local reScaleComp = KTool.GetComponent(self.GoodNode.gameObject, ReverseScaleType)
    if isNotNull(reScaleComp) then
        reScaleComp.scale = 1
        reScaleComp:ResetScale()
    end

    self.goodNodeMB = CfUtils.GetLuaScr(self.GoodNode, GoodsNodeMBPath)
    self.goodNodeMB:Reload({ isShowNo = true , goodsId = data.goodsId, num = data.num, text = "x"..data.num})
    self.goodNodeMB:SetClickCallback(function()
        if self.data.isChoose == 1 and checkNumber(self.data.stock) > 0 then
            self:OnBtnAddClick()
        else
            local vo = GoodsConfMgr:GetInstance():GetGoodsVoById(data.goodsId)
            if isTable(vo) then
                GameUtils.ShowCommonTipsBoard(self.GoodNode, vo.name, vo.desc, vo.quality, vo.id)
            end
        end
    end)
end

function ActivityGachaponTowerEntryRewardNode:OnBtnAddClick()
    local isChoose = (self.data.isChoose == 1)
    if isChoose and checkNumber(self.data.stock) > 0 then
        ActivityGachaponTowerMgr:GetInstance():SaveAddData(self.data)
        local rewards = self:GetAutoSelectRewards()
        UIModule.OpenDialog({ id = Constants.UITypeIds.CommonChooseRewardPopup, parameters = { rewards = rewards} })
    end
end

function ActivityGachaponTowerEntryRewardNode:GetAutoSelectRewards()
    local data = {}

    for i, v in pairs(self.data.chooseRewards) do
        table.insert(data,{ isLockItem = false , goodsId = v.goodsId ,num = v.num })
    end

    for i, v in ipairs(self.data.lockReward) do
        local LockDesc = localize("第_num_轮解锁该奖励",{_num_ = self.data.unlockRound[i] })
        local SelectDesc = localize("_num_轮解锁",{_num_ = self.data.unlockRound[i] })
        table.insert(data,{ isLockItem = true , goodsId = v.goodsId ,num = v.num, LockDesc = LockDesc, SelectDesc = SelectDesc })
    end

    return data
end

function ActivityGachaponTowerEntryRewardNode:OnDestroy()
    self.controller = nil --删除lua层引⽤到的c#对象否则不会产⽣c# gc回收到对象
    self:Delete()
end

return ActivityGachaponTowerEntryRewardNode